            manageDatabase.getKwPropertyValue(
                KwConstants.KW_REPORTS_TMP_LOCATION_KEY, TestConstants.TENANT_ID))
        .thenReturn(TestConstants.KW_REPORTS_LOCATION);
    Mockito.doReturn(listTeamsOverview)
        .when(analyticsControllerService)
        .getTeamsOverview(null, 30);
    Mockito.when(commonUtilsService.getEnvsFromUserId(any()))
        .thenReturn(Set.of(TestConstants.ENV_ID));
    Mockito.doReturn(TestConstants.ENV_NAME)
        .when(analyticsControllerService)
        .getEnvName(TestConstants.ENV_ID);
    Mockito.when(
            commonUtilsService.isNotAuthorizedUser(any(), eq(PermissionType.ALL_TEAMS_REPORTS)))
        .thenReturn(false);
    Mockito.when(manageDatabase.getHandleDbRequests()).thenReturn(handleDbRequestsJdbc);
    Mockito.when(handleDbRequestsJdbc.getAllTopics(TestConstants.TENANT_ID))
        .thenReturn(List.of(topic));
    Mockito.when(handleDbRequestsJdbc.getAllConsumerGroups(TestConstants.TENANT_ID))
        .thenReturn(List.of(acl));

    File actual = analyticsControllerService.generateReport(30);
    Assertions.assertNotNull(actual);

    // Verify successful report generation and the workbook inside the ZIP.
    boolean foundReportEntry = false;
    try (ZipInputStream zip = new ZipInputStream(new FileInputStream(actual))) {
        ZipEntry entry;
        while ((entry = zip.getNextEntry()) != null) {
            Assertions.assertEquals("Klaw-team-a.xlsx", entry.getName());
            foundReportEntry = true;

            ByteArrayOutputStream xlsxBytes = new ByteArrayOutputStream();
            zip.transferTo(xlsxBytes);
            Assertions.assertTrue(xlsxBytes.size() > 0);

            try (var workbook =
                WorkbookFactory.create(
                    new java.io.ByteArrayInputStream(xlsxBytes.toByteArray()))) {
                Assertions.assertTrue(workbook.getNumberOfSheets() > 0);
                for (int i = 0; i < workbook.getNumberOfSheets(); i++) {
                    Assertions.assertTrue(
                        workbook.getSheetAt(i).getPhysicalNumberOfRows() > 0);
                }
            }
        }
    }
    Assertions.assertTrue(foundReportEntry);
    Assertions.assertTrue(actual.delete() || !actual.exists());
