@Test
void getRedirectPageReturnFullPathRequestUriQueryTest() {
    when(httpServletRequest.getSession()).thenReturn(httpSession);
    when(httpSession.getAttribute(springSavedReqAttribute)).thenReturn(defaultSavedRequest);

    when(defaultSavedRequest.getRequestURI()).thenReturn("/browseTopics");
    when(defaultSavedRequest.getQueryString()).thenReturn("topicName=testtopic");
    when(defaultSavedRequest.getServletPath()).thenReturn(null);
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("/browseTopics?topicName=testtopic");

    when(defaultSavedRequest.getRequestURI()).thenReturn("/login");
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("index");

    when(defaultSavedRequest.getRequestURI()).thenReturn("/browseTopics");
    when(defaultSavedRequest.getQueryString()).thenReturn(null);
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("/browseTopics");

    when(httpSession.getAttribute(springSavedReqAttribute)).thenReturn(null);
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("index");

    when(httpSession.getAttribute(springSavedReqAttribute)).thenReturn(defaultSavedRequest);
    when(defaultSavedRequest.getRequestURI()).thenReturn(null);
    when(defaultSavedRequest.getQueryString()).thenReturn("topicName=testtopic");
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isNull();

    // A non-provider servlet path follows the normal URI-plus-query redirect.
    when(defaultSavedRequest.getRequestURI()).thenReturn("/browseTopics");
    when(defaultSavedRequest.getQueryString()).thenReturn("topicName=testtopic");
    when(defaultSavedRequest.getServletPath()).thenReturn("/callback");
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("/browseTopics?topicName=testtopic");

    when(defaultSavedRequest.getServletPath()).thenReturn("/{{ provider }}/callback");
    assertThat(kwAuthenticationSuccessHandler.getRedirectPage(httpServletRequest, null))
        .isEqualTo("/");
}

@Test
void deleteTeamFailure() throws KlawException {
    int teamId = 101;
    int tenantId = 101;

    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(false);
    when(handleDbRequests.getUsersInfo(anyString())).thenReturn(userInfo);
    when(commonUtilsService.getTenantId(anyString())).thenReturn(tenantId);
    when(mailService.getUserName(any())).thenReturn("testuser");
    when(manageDatabase.getRolesPermissionsPerTenant(anyInt()))
        .thenReturn(utilMethods.getRolesPermsMap());

    // Existing users take the early failure path.
    when(handleDbRequests.existsUsersInfoForTeam(teamId, tenantId)).thenReturn(true);
    ApiResponse apiResponse = usersTeamsControllerService.deleteTeam(teamId);
    assertThat(apiResponse.getMessage())
        .isEqualTo("Not allowed to delete this team, as there are associated users.");

    // An unauthorized user is rejected before association checks.
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(true);
    apiResponse = usersTeamsControllerService.deleteTeam(teamId);
    assertThat(apiResponse).isEqualTo(ApiResponse.NOT_AUTHORIZED);

    // With no associated users, a team with components is rejected.
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(false);
    when(handleDbRequests.existsUsersInfoForTeam(teamId, tenantId)).thenReturn(false);
    when(handleDbRequests.existsComponentsCountForTeam(teamId, tenantId)).thenReturn(true);
    apiResponse = usersTeamsControllerService.deleteTeam(teamId);
    assertThat(apiResponse.getMessage())
        .isEqualTo(
            "Not allowed to delete this team, as there are associated topics/acls/requests/connectors.");
}

