    // TODO: Populate tenantModel with environment references that updateEnvNameValues resolves.
    config.setTenantModel(null);

    Map<String, Map<String, String>> dbObject = new HashMap<>();
    Map<String, String> configMap = new HashMap<>();
    configMap.put("kwvalue", mapper.writeValueAsString(config));
    configMap.put("kwdesc", "Desc");
    dbObject.put(KLAW_TENANT_CONFIG, configMap);

    // Include a non-config entry to cover the pass-through branch.
    Map<String, String> otherMap = new HashMap<>();
    otherMap.put("kwvalue", "original value");
    otherMap.put("kwdesc", "Other description");
    dbObject.put("some.other.property", otherMap);

    when(managedb.getKwPropertiesMap(101)).thenReturn(dbObject);

    List<KwPropertiesResponse> response = serverConfigService.getAllEditableProps();

    assertThat(response).hasSize(2);
    KwPropertiesResponse tenantResponse =
        response.stream()
            .filter(item -> KLAW_TENANT_CONFIG.equals(item.getKwkey()))
            .findFirst()
            .orElseThrow();
    assertThat(tenantResponse.getKwkey()).isEqualTo(KLAW_TENANT_CONFIG);
    assertThat(tenantResponse.getKwdesc()).isEqualTo("Desc");
    TenantConfig tenantConfig =
        mapper.readValue(tenantResponse.getKwvalue(), TenantConfig.class);
    assertThat(tenantConfig.getTenantModel()).isNull();

    KwPropertiesResponse otherResponse =
        response.stream()
            .filter(item -> "some.other.property".equals(item.getKwkey()))
            .findFirst()
            .orElseThrow();
    assertThat(otherResponse.getKwvalue()).isEqualTo("original value");
    assertThat(otherResponse.getKwdesc()).isEqualTo("Other description");

    verify(managedb, times(1)).getKwPropertiesMap(101);
}

