@Test
@Order(40)
public void declineTopicRequestsFailureRequestDoesNotExist() throws KlawException {
    String topicId = "1001";
    TopicRequest topicRequest = getTopicRequest("testtopic");

    stubUserInfo();

    // A request that is no longer CREATED should report that it no longer exists.
    topicRequest.setRequestStatus(RequestStatus.APPROVED.value);
    when(handleDbRequests.selectTopicRequestsForTopic(anyInt(), anyInt()))
        .thenReturn(topicRequest);
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(false);

    ApiResponse resultResp = topicControllerService.declineTopicRequests(topicId, "Reason");
    assertThat(resultResp.getResult()).isEqualTo("This request does not exist anymore.");

    // Authorization is checked before the request is loaded.
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(true);
    resultResp = topicControllerService.declineTopicRequests(topicId, "Reason");
    assertThat(resultResp.getResult()).isEqualTo(ApiResultStatus.NOT_AUTHORIZED.value);

    // A CREATED request in an unauthorized environment must also be rejected.
    topicRequest.setRequestStatus(RequestStatus.CREATED.value);
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(false);
    when(commonUtilsService.getEnvsFromUserId(anyString())).thenReturn(Collections.emptySet());
    resultResp = topicControllerService.declineTopicRequests(topicId, "Reason");
    assertThat(resultResp.getResult()).isEqualTo(ApiResultStatus.NOT_AUTHORIZED.value);

    // With an allowed environment, CREATED requests proceed through the decline path.
    when(commonUtilsService.getEnvsFromUserId(anyString())).thenReturn(Set.of(env.getId()));
    when(handleDbRequests.declineTopicRequest(any(), anyString()))
        .thenReturn(ApiResultStatus.SUCCESS.value);
    resultResp = topicControllerService.declineTopicRequests(topicId, "Reason");
    assertThat(resultResp.getResult()).isNotEqualTo("This request does not exist anymore.");
}

