@Test
@Order(10)
public void createTopicDeleteRequestSuccessDefaultValues() {
    String topicName = "testtopic1";
    String envId = "1";
    String userName = "kwusera";
    stubUserInfo();
    when(commonUtilsService.getTeamId(anyString())).thenReturn(1);
    when(commonUtilsService.isNotAuthorizedUser(any(), any())).thenReturn(false);
    when(commonUtilsService.getTenantId(anyString())).thenReturn(101);

    // Preserve the successful matching-environment, no-ACL path and inspect the persisted request.
    when(handleDbRequests.selectTopicRequests(
            eq(topicName), eq(envId), eq(RequestStatus.CREATED.value), eq(101)))
        .thenReturn(Collections.emptyList());
    when(handleDbRequests.getTopicTeam(anyString(), anyInt()))
        .thenReturn(List.of(getTopic(topicName)));
    when(commonUtilsService.getFilteredTopicsForTenant(any()))
        .thenReturn(List.of(getTopic(topicName)));
    when(handleDbRequests.getSyncAcls(anyString(), anyString(), anyInt()))
        .thenReturn(Collections.emptyList());
    Map<String, String> deleteReqResult = new HashMap<>();
    deleteReqResult.put("result", ApiResultStatus.SUCCESS.value);
    when(handleDbRequests.requestForTopic(any())).thenReturn(deleteReqResult);

    try {
        ApiResponse apiResponse = topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(apiResponse.getResult()).isEqualTo(ApiResultStatus.SUCCESS.value);
        verify(commonUtilsService).isNotAuthorizedUser(any(), eq(PermissionType.REQUEST_DELETE_TOPICS));

        ArgumentCaptor<TopicRequest> requestCaptor = ArgumentCaptor.forClass(TopicRequest.class);
        verify(handleDbRequests).requestForTopic(requestCaptor.capture());
        TopicRequest captured = requestCaptor.getValue();
        assertThat(captured.getRequestor()).isEqualTo(userName);
        assertThat(captured.getUsername()).isEqualTo(userName);
        assertThat(captured.getTeamId()).isEqualTo(1);
        assertThat(captured.getEnvironment()).isEqualTo(envId);
        assertThat(captured.getTopicname()).isEqualTo(topicName);
        assertThat(captured.getTenantId()).isEqualTo(101);

        // Cover duplicate-request rejection.
        when(handleDbRequests.selectTopicRequests(
                eq(topicName), eq(envId), eq(RequestStatus.CREATED.value), eq(101)))
            .thenReturn(List.of(new TopicRequest()));
        ApiResponse duplicateResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(duplicateResponse.getResult()).isNotEqualTo(ApiResultStatus.SUCCESS.value);
        verify(handleDbRequests, times(1)).requestForTopic(any());

        // Cover a requester whose team does not own the topic.
        when(handleDbRequests.selectTopicRequests(
                eq(topicName), eq(envId), eq(RequestStatus.CREATED.value), eq(101)))
            .thenReturn(Collections.emptyList());
        when(commonUtilsService.getTeamId(anyString())).thenReturn(2);
        ApiResponse wrongTeamResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(wrongTeamResponse.getResult()).isNotEqualTo(ApiResultStatus.SUCCESS.value);

        // Cover no topic matching the requested environment.
        when(commonUtilsService.getTeamId(anyString())).thenReturn(1);
        Topic otherEnvironmentTopic = getTopic(topicName);
        otherEnvironmentTopic.setEnvironment("2");
        when(commonUtilsService.getFilteredTopicsForTenant(any()))
            .thenReturn(List.of(otherEnvironmentTopic));
        ApiResponse missingTopicResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(missingTopicResponse.getResult())
            .isEqualTo("Failure. Topic not found on cluster: " + topicName);

        // Cover a matching topic that already has synchronized ACLs.
        when(commonUtilsService.getFilteredTopicsForTenant(any()))
            .thenReturn(List.of(getTopic(topicName)));
        when(handleDbRequests.getSyncAcls(anyString(), anyString(), anyInt()))
            .thenReturn(List.of(new Acl()));
        ApiResponse existingAclResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(existingAclResponse.getResult()).isNotEqualTo(ApiResultStatus.SUCCESS.value);

        // Cover null and empty topic-list handling.
        when(commonUtilsService.getFilteredTopicsForTenant(any())).thenReturn(null);
        ApiResponse nullTopicsResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(nullTopicsResponse.getResult())
            .isEqualTo("Failure. Topic not found on cluster: " + topicName);

        when(commonUtilsService.getFilteredTopicsForTenant(any()))
            .thenReturn(Collections.emptyList());
        ApiResponse emptyTopicsResponse =
            topicControllerService.createTopicDeleteRequest(topicName, envId);
        assertThat(emptyTopicsResponse.getResult())
            .isEqualTo("Failure. Topic not found on cluster: " + topicName);
    } catch (KlawException | KlawNotAuthorizedException e) {
        throw new RuntimeException(e);
    }
}

