@Test
public void testBuildWithNacosException() {
    int errCode = 500;
    String errMsg = "nacos exception msg";
    NacosException nacosException = new NacosException(errCode, errMsg);

    Response response = ErrorResponse.build(nacosException);

    Assert.assertEquals(errCode, response.getErrorCode());
    Assert.assertEquals(errMsg, response.getMessage());
    Assert.assertEquals(errCode, response.getResultCode());

    int runtimeErrCode = 501;
    String runtimeErrMsg = "nacos runtime exception msg";
    NacosRuntimeException nacosRuntimeException =
            new NacosRuntimeException(runtimeErrCode, runtimeErrMsg);

    Response runtimeResponse = ErrorResponse.build(nacosRuntimeException);

    Assert.assertEquals(runtimeErrCode, runtimeResponse.getErrorCode());
    Assert.assertEquals(runtimeErrCode, runtimeResponse.getResultCode());
    // NacosRuntimeException exposes its message in formatted error-information form.
    Assert.assertEquals("errCode: 501, errMsg: nacos runtime exception msg ", runtimeResponse.getMessage());

    String plainErrMsg = "plain runtime exception msg";
    RuntimeException runtimeException = new RuntimeException(plainErrMsg);

    Response fallbackResponse = ErrorResponse.build(runtimeException);

    Assert.assertEquals(ResponseCode.FAIL.getCode(), fallbackResponse.getErrorCode());
    Assert.assertEquals(ResponseCode.FAIL.getCode(), fallbackResponse.getResultCode());
    Assert.assertEquals(plainErrMsg, fallbackResponse.getMessage());
}

@Test
public void testBuildWithNacosRuntimeException() {
    int errCode = 501;
    String errMsg = "nacos runtime exception msg";
    NacosRuntimeException nacosRuntimeException = new NacosRuntimeException(errCode, errMsg);

    Response response = ErrorResponse.build(nacosRuntimeException);

    Assert.assertNotNull(response);
    Assert.assertEquals(errCode, response.getErrorCode());
    Assert.assertEquals("errCode: " + errCode + ", errMsg: " + errMsg + " ", response.getMessage());
    // Use a non-default error code so setting the result code is observable.
    Assert.assertEquals(errCode, response.getResultCode());

    NacosException nacosException = new NacosException(errCode, errMsg);
    Response nacosResponse = ErrorResponse.build(nacosException);
    Assert.assertNotNull(nacosResponse);
    Assert.assertEquals(errCode, nacosResponse.getErrorCode());
    Assert.assertEquals(nacosException.getMessage(), nacosResponse.getMessage());

    RuntimeException runtimeException = new RuntimeException("failure");
    Response fallbackResponse = ErrorResponse.build(runtimeException);
    Assert.assertNotNull(fallbackResponse);
    Assert.assertEquals(ResponseCode.FAIL.getCode(), fallbackResponse.getErrorCode());
    Assert.assertEquals(runtimeException.getMessage(), fallbackResponse.getMessage());
}

