@Test
public void testForwardMessageToDeadLetterQueueWhenHasMappingHandle() throws Throwable {
    ArgumentCaptor<ReceiptHandle> receiptHandleCaptor = ArgumentCaptor.forClass(ReceiptHandle.class);
    when(this.messagingProcessor.forwardMessageToDeadLetterQueue(
        any(), receiptHandleCaptor.capture(), anyString(), anyString(), anyString()))
        .thenReturn(CompletableFuture.completedFuture(
            RemotingCommand.createResponseCommand(ResponseCode.SUCCESS, "")));

    String requestHandle = buildReceiptHandle("topic", System.currentTimeMillis(), 3000);
    when(receiptHandleProcessor.removeReceiptHandle(
        any(), any(), anyString(), anyString(), anyString()))
        .thenReturn(new MessageReceiptHandle(
            "group", "topic", 0, requestHandle, "msgId", 0, 0));

    ForwardMessageToDeadLetterQueueResponse response =
        this.forwardMessageToDLQActivity.forwardMessageToDeadLetterQueue(
            createContext(),
            ForwardMessageToDeadLetterQueueRequest.newBuilder()
                .setTopic(Resource.newBuilder().setName("topic").build())
                .setGroup(Resource.newBuilder().setName("group").build())
                .setMessageId(MessageClientIDSetter.createUniqID())
                .setReceiptHandle(requestHandle)
                .build())
            .get();

    assertEquals(Code.OK, response.getStatus().getCode());
    assertEquals(requestHandle, receiptHandleCaptor.getValue().getReceiptHandle());

    // With no mapping, the activity forwards the decoded request handle unchanged.
    reset(receiptHandleProcessor);
    reset(messagingProcessor);
    receiptHandleCaptor = ArgumentCaptor.forClass(ReceiptHandle.class);
    when(receiptHandleProcessor.removeReceiptHandle(
        any(), any(), anyString(), anyString(), anyString()))
        .thenReturn(null);
    when(messagingProcessor.forwardMessageToDeadLetterQueue(
        any(), receiptHandleCaptor.capture(), anyString(), anyString(), anyString()))
        .thenReturn(CompletableFuture.completedFuture(
            RemotingCommand.createResponseCommand(ResponseCode.SUCCESS, "")));

    response = this.forwardMessageToDLQActivity.forwardMessageToDeadLetterQueue(
        createContext(),
        ForwardMessageToDeadLetterQueueRequest.newBuilder()
            .setTopic(Resource.newBuilder().setName("topic").build())
            .setGroup(Resource.newBuilder().setName("group").build())
            .setMessageId(MessageClientIDSetter.createUniqID())
            .setReceiptHandle(requestHandle)
            .build())
        .get();

    assertEquals(Code.OK, response.getStatus().getCode());
    assertEquals(ReceiptHandle.decode(requestHandle).getReceiptHandle(),
        receiptHandleCaptor.getValue().getReceiptHandle());

    // Invalid resources should fail validation without reaching the forwarding processor.
    reset(messagingProcessor);
    try {
        this.forwardMessageToDLQActivity.forwardMessageToDeadLetterQueue(
            createContext(),
            ForwardMessageToDeadLetterQueueRequest.newBuilder()
                .setTopic(Resource.newBuilder().setName("").build())
                .setGroup(Resource.newBuilder().setName("group").build())
                .setMessageId(MessageClientIDSetter.createUniqID())
                .setReceiptHandle(requestHandle)
                .build())
            .get();
        fail("Expected invalid topic validation to fail");
    } catch (Exception expected) {
        assertNotNull(expected.getCause() == null ? expected : expected.getCause());
    }

    verify(messagingProcessor, never()).forwardMessageToDeadLetterQueue(
        any(), any(), anyString(), anyString(), anyString());
}

