            + "{\"appName\":\"null-gray\",\"upstreamUrl\":\"http://example.com/null-gray\"}"
            + "]");
    handler.handlerSelector(graySelector);

    SelectorData emptyGraySelector = new SelectorData();
    emptyGraySelector.setId("empty-gray");
