@Test
public void testCheckData() {
    SentinelHandle handle = new SentinelHandle();
    handle.setFlowRuleEnable(Constants.FLOW_RULE_ENABLE_OFF);
    handle.setDegradeRuleEnable(Constants.DEGRADE_RULE_ENABLE_OFF);

    // OFF values are valid and should remain unchanged.
    handle.checkData();

    assertThat(handle.getFlowRuleEnable(), is(Constants.FLOW_RULE_ENABLE_OFF));
    assertThat(handle.getDegradeRuleEnable(), is(Constants.DEGRADE_RULE_ENABLE_OFF));

    // ON values are also valid and should remain unchanged.
    handle.setFlowRuleEnable(Constants.FLOW_RULE_ENABLE_ON);
    handle.setDegradeRuleEnable(Constants.DEGRADE_RULE_ENABLE_ON);
    handle.checkData();

    assertThat(handle.getFlowRuleEnable(), is(Constants.FLOW_RULE_ENABLE_ON));
    assertThat(handle.getDegradeRuleEnable(), is(Constants.DEGRADE_RULE_ENABLE_ON));

    // Invalid values fall back to their respective defaults.
    handle.setFlowRuleEnable(-1);
    handle.setDegradeRuleEnable(3);
    handle.checkData();

    assertThat(handle.getFlowRuleEnable(), is(Constants.SENTINEL_ENABLE_FLOW_RULE));
    assertThat(handle.getDegradeRuleEnable(), is(Constants.SENTINEL_ENABLE_DEGRADE_RULE));
}

