@Test
public void executeTest() {
    // A missing cached handle should pass execution through to the chain.
    CACHED_HANDLE.get().removeHandle(CacheKeyUtils.INST.getKey(ruleData));
    Mono<Void> missingHandleResult = contextPathPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(missingHandleResult);
    verify(chain).execute(exchange);

    ContextMappingRuleHandle contextMappingRuleHandle = new ContextMappingRuleHandle();
    contextMappingRuleHandle.setContextPath("/http/context");
    CACHED_HANDLE.get().cachedHandle(CacheKeyUtils.INST.getKey(ruleData), contextMappingRuleHandle);
    when(ruleData.getHandle()).thenReturn(GsonUtils.getGson().toJson(contextMappingRuleHandle));

    // A matching path should build the real URL and return the chain publisher.
    reset(chain);
    when(chain.execute(exchange)).thenReturn(Mono.empty());
    shenyuContext.setPath("/http/context/order/findById");
    Mono<Void> validResult = contextPathPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(validResult);
    Assert.assertEquals("/order/findById", shenyuContext.getRealUrl());
    verify(chain).execute(exchange);

    // An invalid prefix should produce the context-path error without invoking the chain.
    reset(chain);
    shenyuContext.setPath("/http/other/order/findById");
    Mono<Void> invalidResult = contextPathPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(invalidResult);
    StepVerifier.create(invalidResult)
            .expectNext()
            .verifyComplete();
    verify(chain, never()).execute(exchange);
}

