@Test
public void testFilter() {
    ShenyuConfig.CrosFilterConfig config = new ShenyuConfig.CrosFilterConfig();
    config.setAllowedOrigin("https://test.example");
    config.setAllowedMethods("GET,POST");
    config.setMaxAge("1234");
    config.setAllowedHeaders("X-Custom-Request");
    config.setAllowedExpose("X-Custom-Response");
    config.setAllowCredentials(false);

    ServerWebExchange exchangeNoHeader = MockServerWebExchange.from(MockServerHttpRequest
            .get("http://localhost:8080")
            .build());
    WebFilterChain chainNoHeader = mock(WebFilterChain.class);
    when(chainNoHeader.filter(exchangeNoHeader)).thenReturn(Mono.empty());
    CrossFilter filterNoHeader = new CrossFilter(config);
    StepVerifier.create(filterNoHeader.filter(exchangeNoHeader, chainNoHeader))
            .verifyComplete();

    assertNull(exchangeNoHeader.getResponse().getHeaders().getFirst("Access-Control-Allow-Origin"));
    verify(chainNoHeader, times(1)).filter(exchangeNoHeader);

    ServerWebExchange exchangeNormal = MockServerWebExchange.from(MockServerHttpRequest
            .get("http://localhost:8080")
            .header("Origin", "test")
            .build());
    WebFilterChain chainNormal = mock(WebFilterChain.class);
    when(chainNormal.filter(exchangeNormal)).thenReturn(Mono.empty());
    CrossFilter filterNormal = new CrossFilter(config);
    StepVerifier.create(filterNormal.filter(exchangeNormal, chainNormal))
            .verifyComplete();

    assertEquals("https://test.example",
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Allow-Origin"));
    assertEquals("GET,POST",
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Allow-Methods"));
    assertEquals("1234",
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Max-Age"));
    assertEquals(config.getAllowedHeaders(),
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Allow-Headers"));
    assertEquals("X-Custom-Response",
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Expose-Headers"));
    assertEquals("false",
            exchangeNormal.getResponse().getHeaders().getFirst("Access-Control-Allow-Credentials"));
    verify(chainNormal, times(1)).filter(exchangeNormal);

    ServerWebExchange exchangeOption = MockServerWebExchange.from(MockServerHttpRequest
            .options("http://localhost:8080")
            .header("Origin", "test")
            .build());
    WebFilterChain chainOption = mock(WebFilterChain.class);
    when(chainOption.filter(exchangeOption)).thenReturn(Mono.empty());
    CrossFilter filterOption = new CrossFilter(config);
    StepVerifier.create(filterOption.filter(exchangeOption, chainOption))
            .verifyComplete();

    assertEquals(HttpStatus.OK, exchangeOption.getResponse().getStatusCode());
    assertEquals("https://test.example",
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Allow-Origin"));
    assertEquals("GET,POST",
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Allow-Methods"));
    assertEquals("1234",
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Max-Age"));
    assertEquals(config.getAllowedHeaders(),
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Allow-Headers"));
    assertEquals("X-Custom-Response",
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Expose-Headers"));
    assertEquals("false",
            exchangeOption.getResponse().getHeaders().getFirst("Access-Control-Allow-Credentials"));
    verify(chainOption, never()).filter(exchangeOption);
}

