    Mono<Void> result = contextPathMappingPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(result);
    Assert.assertEquals("/findById", soulContext.getRealUrl());

    // Missing cache delegates to the chain; include the successful call in the count.
    ApplicationConfigCache.getInstance().removeHandle(cacheKey);
    Mono<Void> missingHandleResult = contextPathMappingPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(missingHandleResult);
    verify(chain, org.mockito.Mockito.times(2)).execute(exchange);

    // A cached mapping with a blank context path also delegates to the chain.
    ContextMappingHandle blankPathHandle = new ContextMappingHandle();
    blankPathHandle.setContextPath("");
    ApplicationConfigCache.getInstance().cachedHandle(cacheKey, blankPathHandle);
    Mono<Void> blankPathResult = contextPathMappingPlugin.doExecute(exchange, chain, selectorData, ruleData);
    Assert.assertNotNull(blankPathResult);
    verify(chain, org.mockito.Mockito.times(3)).execute(exchange);
}

