@Test
public void processShouldReturnExpectedResultIfRejectedBySomeOfProcessors() {
    final BidRequest bidRequest = BidRequest.builder().build();
    final BidderError firstError = BidderError.badInput("Error from mediaTypeProcessor1");
    final BidderError secondError = BidderError.badInput("Error from mediaTypeProcessor2");

    // The first processor rejects, so the composite should skip the second processor.
    given(mediaTypeProcessor1.process(any(), anyString(), any(), any()))
            .willReturn(MediaTypeProcessingResult.rejected(singletonList(firstError)));

    final MediaTypeProcessingResult firstRejectedResult = target.process(
            bidRequest, "bidder", bidderAliases, null);

    assertThat(firstRejectedResult.isRejected()).isTrue();
    assertThat(firstRejectedResult.getErrors()).containsExactly(firstError);
    verifyNoInteractions(mediaTypeProcessor2);

    // If the first processor succeeds, processing continues and a later rejection is returned.
    given(mediaTypeProcessor1.process(any(), anyString(), any(), any()))
            .willReturn(MediaTypeProcessingResult.succeeded(bidRequest, singletonList(firstError)));
    given(mediaTypeProcessor2.process(any(), anyString(), any(), any()))
            .willReturn(MediaTypeProcessingResult.rejected(singletonList(secondError)));

    final MediaTypeProcessingResult secondRejectedResult = target.process(
            bidRequest, "bidder", bidderAliases, null);

    assertThat(secondRejectedResult.isRejected()).isTrue();
    assertThat(secondRejectedResult.getErrors()).containsExactly(firstError, secondError);
    org.mockito.Mockito.verify(mediaTypeProcessor2).process(bidRequest, "bidder", bidderAliases, null);

    // When both processors succeed, the final result remains successful and aggregates errors.
    given(mediaTypeProcessor2.process(any(), anyString(), any(), any()))
            .willReturn(MediaTypeProcessingResult.succeeded(bidRequest, singletonList(secondError)));

    final MediaTypeProcessingResult successfulResult = target.process(
            bidRequest, "bidder", bidderAliases, null);

    assertThat(successfulResult.isRejected()).isFalse();
    assertThat(successfulResult.getErrors()).containsExactly(firstError, secondError);
    org.mockito.Mockito.verify(mediaTypeProcessor2, org.mockito.Mockito.times(2))
            .process(bidRequest, "bidder", bidderAliases, null);
}

