@Test
public void gpcFromShouldReturn1OnInteger() {
    // given: the header name changed; verify both accepted forms and non-matching inputs.
    final HttpRequestContext unquotedRequest = HttpRequestContext.builder()
            .headers(CaseInsensitiveMultiMap.builder()
                    .add(HttpUtil.SEC_GPC_HEADER, "1")
                    .build())
            .build();

    final HttpRequestContext quotedRequest = HttpRequestContext.builder()
            .headers(CaseInsensitiveMultiMap.builder()
                    .add(HttpUtil.SEC_GPC_HEADER, "\"1\"")
                    .build())
            .build();

    final HttpRequestContext nonMatchingRequest = HttpRequestContext.builder()
            .headers(CaseInsensitiveMultiMap.builder()
                    .add(HttpUtil.SEC_GPC_HEADER, "0")
                    .build())
            .build();

    final HttpRequestContext missingHeaderRequest = HttpRequestContext.builder()
            .headers(CaseInsensitiveMultiMap.builder().build())
            .build();

    // then
    assertThat(extractor.gpcFrom(unquotedRequest)).isEqualTo("1");
    assertThat(extractor.gpcFrom(quotedRequest)).isEqualTo("1");
