    final User result = privacyEnforcementService.maskUserConsideringActivityRestrictions(user, true, true);
    assertThat(result).isEqualTo(User.builder()
            .id(null)
            .buyeruid(null)
            .yob(null)
            .gender(null)
            .data(null)
