@Test
public void testAutoRenewOrderCertificate() throws Exception {
    var autoRenewStart = parseTimestamp("2018-01-01T00:00:00Z");
    var autoRenewEnd = parseTimestamp("2019-01-01T00:00:00Z");
    var validity = Duration.ofDays(7);
    var predate = Duration.ofDays(6);

    // An order must contain at least one identifier.
    var emptyProvider = new TestableConnectionProvider();
    var emptyLogin = emptyProvider.createLogin();
    var emptyAccount = new Account(emptyLogin);
    try {
        assertThatThrownBy(() -> emptyAccount.newOrder().create())
                .isInstanceOf(IllegalArgumentException.class)
                .hasMessage("At least one identifer is required");
    } finally {
        emptyProvider.close();
    }

    // Auto-renewal is rejected before any request is sent when unsupported.
    var unsupportedProvider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login login) {
            throw new AssertionError("No request should be sent when auto-renewal is unsupported");
        }
    };
    unsupportedProvider.putTestResource(Resource.NEW_ORDER, resourceUrl);
    var unsupportedLogin = unsupportedProvider.createLogin();
    var unsupportedAccount = new Account(unsupportedLogin);
    var unsupportedOrder = unsupportedAccount.newOrder()
            .domain("example.org")
            .autoRenewal()
            .autoRenewalStart(autoRenewStart);
    try {
        assertThatThrownBy(unsupportedOrder::create)
                .isInstanceOf(AcmeException.class)
                .hasMessage("CA does not support short-term automatic renewals");
    } finally {
        unsupportedProvider.close();
    }

    var provider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login login) {
            assertThat(url).isEqualTo(resourceUrl);
            assertThatJson(claims.toString())
                    .isEqualTo(getJSON("requestAutoRenewOrderRequest").toString());
            assertThat(login).isNotNull();
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public JSON readJsonResponse() {
            return getJSON("requestAutoRenewOrderResponse");
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.of(locationUrl);
        }
    };

    var login = provider.createLogin();
    provider.putMetadata("auto-renewal", JSON.empty());
    provider.putTestResource(Resource.NEW_ORDER, resourceUrl);

    var account = new Account(login);
    var order = account.newOrder()
            .domain("example.org")
            .autoRenewal()
            .autoRenewalStart(autoRenewStart)
            .autoRenewalEnd(autoRenewEnd)
            .autoRenewalLifetime(validity)
            .autoRenewalLifetimeAdjust(predate)
            .autoRenewalEnableGet()
            .create();

    try (var softly = new AutoCloseableSoftAssertions()) {
        softly.assertThat(order.getIdentifiers()).containsExactlyInAnyOrder(Identifier.dns("example.org"));
        softly.assertThat(order.getNotBefore()).isEmpty();
        softly.assertThat(order.getNotAfter()).isEmpty();
        softly.assertThat(order.isAutoRenewing()).isTrue();
        softly.assertThat(order.getAutoRenewalStartDate()).contains(autoRenewStart);
        softly.assertThat(order.getAutoRenewalEndDate()).contains(autoRenewEnd);
        softly.assertThat(order.getAutoRenewalLifetime()).contains(validity);
        softly.assertThat(order.getAutoRenewalLifetimeAdjust()).contains(predate);
        softly.assertThat(order.isAutoRenewalGetEnabled()).isTrue();
        softly.assertThat(order.getLocation()).isEqualTo(locationUrl);
    }

    provider.close();
}

