@Test
public void testRegistration() throws Exception {
    var accountKey = TestUtils.createKeyPair();

    // Verify the missing key pair is rejected before any request is sent.
    var missingKeyProvider = new TestableConnectionProvider();
    var missingKeyBuilder = new AccountBuilder();
    var missingKeySession = missingKeyProvider.createSession();
    assertThatExceptionOfType(IllegalStateException.class)
            .isThrownBy(() -> missingKeyBuilder.createLogin(missingKeySession))
            .withMessage("Use AccountBuilder.useKeyPair() to set the account's key pair.");
    missingKeyProvider.close();

    // Check that optional claims are omitted when not configured, and that onlyExisting is sent.
    var existingOnlyProvider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login login) {
            assertThat(url).isEqualTo(locationUrl);
            assertThat(claims.toString()).doesNotContain("\"contact\"");
            assertThat(claims.toString()).doesNotContain("\"termsOfServiceAgreed\"");
            assertThatJson(claims.toString()).isEqualTo("{\"onlyReturnExisting\":true}");
            return HttpURLConnection.HTTP_OK;
        }

        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Session session, KeyPair keyPair) {
            assertThat(url).isEqualTo(resourceUrl);
            assertThat(claims.toString()).doesNotContain("\"contact\"");
            assertThat(claims.toString()).doesNotContain("\"termsOfServiceAgreed\"");
            assertThatJson(claims.toString()).isEqualTo("{\"onlyReturnExisting\":true}");
            assertThat(keyPair).isEqualTo(accountKey);
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.of(locationUrl);
        }

        @Override
        public JSON readJsonResponse() {
            return getJSON("newAccountResponse");
        }
    };
    existingOnlyProvider.putTestResource(Resource.NEW_ACCOUNT, resourceUrl);

    var existingOnlyBuilder = new AccountBuilder();
    existingOnlyBuilder.useKeyPair(accountKey);
    existingOnlyBuilder.onlyExisting();
    var existingOnlyLogin = existingOnlyBuilder.createLogin(existingOnlyProvider.createSession());
    assertThat(existingOnlyLogin.getAccountLocation()).isEqualTo(locationUrl);
    existingOnlyProvider.close();

    var provider = new TestableConnectionProvider() {
        private boolean isUpdate;

        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login login) {
            assertThat(login).isNotNull();
            assertThat(url).isEqualTo(locationUrl);
            assertThat(isUpdate).isFalse();
            isUpdate = true;
            return HttpURLConnection.HTTP_OK;
        }

        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Session session, KeyPair keyPair) {
            assertThat(session).isNotNull();
            assertThat(url).isEqualTo(resourceUrl);
            assertThatJson(claims.toString()).isEqualTo(getJSON("newAccount").toString());
            assertThat(keyPair).isEqualTo(accountKey);
            isUpdate = false;
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.of(locationUrl);
        }

        @Override
        public JSON readJsonResponse() {
            return getJSON("newAccountResponse");
        }
    };

    provider.putTestResource(Resource.NEW_ACCOUNT, resourceUrl);

    var builder = new AccountBuilder();
    builder.addContact("mailto:foo@example.com");
    builder.agreeToTermsOfService();
    builder.useKeyPair(accountKey);

    var session = provider.createSession();
    var login = builder.createLogin(session);

    assertThat(login.getAccountLocation()).isEqualTo(locationUrl);

    var account = login.getAccount();
    assertThat(account.getTermsOfServiceAgreed()).isEqualTo(Optional.of(true));
    assertThat(account.getLocation()).isEqualTo(locationUrl);
    assertThat(account.hasExternalAccountBinding()).isFalse();
    assertThat(account.getKeyIdentifier()).isEmpty();

    provider.close();

    // An empty Location result must produce the protocol exception with its exact message.
    var noLocationProvider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Session session, KeyPair keyPair) {
            assertThat(url).isEqualTo(resourceUrl);
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.empty();
        }
    };
    noLocationProvider.putTestResource(Resource.NEW_ACCOUNT, resourceUrl);

    var noLocationBuilder = new AccountBuilder();
    noLocationBuilder.useKeyPair(accountKey);
    assertThatExceptionOfType(AcmeProtocolException.class)
            .isThrownBy(() -> noLocationBuilder.createLogin(noLocationProvider.createSession()))
            .withMessage("Server did not provide an account location");
    noLocationProvider.close();
}

