            assertThat(login).isNotNull();
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public JSON readJsonResponse() {
            return getJSON("requestOrderResponse");
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.of(locationUrl);
        }
    };

    var login = provider.createLogin();
    provider.putTestResource(Resource.NEW_ORDER, resourceUrl);

    var account = new Account(login);

    // An order without identifiers is rejected before any request is sent.
    assertThatThrownBy(() -> account.newOrder().create())
            .isInstanceOf(IllegalArgumentException.class)
            .hasMessage("At least one identifer is required");

    // Missing validity bounds are omitted from the request claims.
    var optionalDatesProvider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login requestLogin) {
            assertThatJson(claims.toString())
                    .when(IGNORING_EXTRA_ARRAY_ITEMS)
                    .isEqualTo("{\"identifiers\":[{\"type\":\"dns\",\"value\":\"example.com\"}]}");
            assertThat(claims.toString()).doesNotContain("notBefore", "notAfter");
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public JSON readJsonResponse() {
            return getJSON("requestOrderResponse");
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.of(locationUrl);
        }
    };
    var optionalDatesLogin = optionalDatesProvider.createLogin();
    optionalDatesProvider.putTestResource(Resource.NEW_ORDER, resourceUrl);
    new Account(optionalDatesLogin).newOrder().domain("example.com").create();

    // An empty location Optional triggers the protocol error.
    var missingLocationProvider = new TestableConnectionProvider() {
        @Override
        public int sendSignedRequest(URL url, JSONBuilder claims, Login requestLogin) {
            return HttpURLConnection.HTTP_CREATED;
        }

        @Override
        public Optional<URL> getLocation() {
            return Optional.empty();
        }
    };
    var missingLocationLogin = missingLocationProvider.createLogin();
    missingLocationProvider.putTestResource(Resource.NEW_ORDER, resourceUrl);
    assertThatThrownBy(() -> new Account(missingLocationLogin).newOrder()
            .domain("example.com")
            .create())
            .isInstanceOf(AcmeProtocolException.class)
            .hasMessage("Server did not provide an order location");

    var order = account.newOrder()
            .domains("example.com", "www.example.com")
            .domain("example.org")
            .domains(Arrays.asList("m.example.com", "m.example.org"))
            .identifier(Identifier.dns("d.example.com"))
            .identifiers(Arrays.asList(
                    Identifier.dns("d2.example.com"),
                    Identifier.ip(InetAddress.getByName("192.168.1.2"))))
            .notBefore(notBefore)
            .notAfter(notAfter)
            .create();

    try (var softly = new AutoCloseableSoftAssertions()) {
        softly.assertThat(order.getIdentifiers()).containsExactlyInAnyOrder(
                Identifier.dns("example.com"),
                Identifier.dns("www.example.com"),
                Identifier.dns("example.org"),
                Identifier.dns("m.example.com"),
                Identifier.dns("m.example.org"),
                Identifier.dns("d.example.com"),
                Identifier.dns("d2.example.com"),
                Identifier.ip(InetAddress.getByName("192.168.1.2")));
        softly.assertThat(order.getNotBefore())
                .isEqualTo(Optional.of(parseTimestamp("2016-01-01T00:10:00Z")));
        softly.assertThat(order.getNotAfter())
                .isEqualTo(Optional.of(parseTimestamp("2016-01-08T00:10:00Z")));
        softly.assertThat(order.getExpires())
                .isEqualTo(Optional.of(parseTimestamp("2016-01-10T00:00:00Z")));
        softly.assertThat(order.getStatus()).isEqualTo(Status.PENDING);
        softly.assertThat(order.isAutoRenewing()).isFalse();
        softly.assertThat(order.getAutoRenewalStartDate()).isEmpty();
        softly.assertThat(order.getAutoRenewalEndDate()).isEmpty();
        softly.assertThat(order.getAutoRenewalLifetime()).isEmpty();
        softly.assertThat(order.getAutoRenewalLifetimeAdjust()).isEmpty();
        softly.assertThat(order.isAutoRenewalGetEnabled()).isFalse();
        softly.assertThat(order.getLocation()).isEqualTo(locationUrl);
        softly.assertThat(order.getAuthorizations()).isNotNull();
        softly.assertThat(order.getAuthorizations()).hasSize(2);
    }

    provider.close();
    optionalDatesProvider.close();
    missingLocationProvider.close();
}

@Test
public void testAcmeRateLimitedException() {
    var type = URI.create("urn:ietf:params:acme:error:rateLimited");
    var detail = "Too many requests per minute";
    var retryAfter = Instant.now().plus(Duration.ofMinutes(1));
    var documents = Arrays.asList(
            url("http://example.com/doc1.html"),
            url("http://example.com/doc2.html"));

    var problem = createProblem(type, detail, null);

    var ex = new AcmeRateLimitedException(problem, retryAfter, documents);

    assertThat(ex.getType()).isEqualTo(type);
    assertThat(ex.getMessage()).isEqualTo(detail);
    assertThat(ex.getRetryAfter()).contains(retryAfter);
    assertThat(ex.getDocuments()).containsAll(documents);
}

@Test
public void testUnmarshal() {
    var challenge = new Challenge(TestUtils.login(), getJSON("genericChallenge"));

    // Test unmarshalled values
    try (var softly = new AutoCloseableSoftAssertions()) {
        softly.assertThat(challenge.getType()).isEqualTo("generic-01");
        softly.assertThat(challenge.getStatus()).isEqualTo(Status.INVALID);
        softly.assertThat(challenge.getLocation()).isEqualTo(url("http://example.com/challenge/123"));
        softly.assertThat(challenge.getValidated()).hasValueSatisfying(validated ->
                assertThat(validated).isCloseTo("2015-12-12T17:19:36.336Z", within(1, ChronoUnit.MILLIS)));
        softly.assertThat(challenge.getJSON().get("type").asString()).isEqualTo("generic-01");
        softly.assertThat(challenge.getJSON().get("url").asURL()).isEqualTo(url("http://example.com/challenge/123"));

        var error = challenge.getError();
        softly.assertThat(error).isPresent();
        error.ifPresent(problem -> {
            softly.assertThat(problem.getType()).isEqualTo(URI.create("urn:ietf:params:acme:error:incorrectResponse"));
            softly.assertThat(problem.getDetail()).hasValue("bad token");
            softly.assertThat(problem.getInstance()).hasValue(URI.create("http://example.com/documents/faq.html"));
        });
    }
}

@Test
public void testProblem() {
    var baseUrl = url("https://example.com/acme/1");
    var original = TestUtils.getJSON("problem");

    var problem = new Problem(original, baseUrl);

    assertThatJson(problem.asJSON().toString()).isEqualTo(original.toString());

    try (var softly = new AutoCloseableSoftAssertions()) {
        softly.assertThat(problem.getType()).isEqualTo(URI.create("urn:ietf:params:acme:error:malformed"));
        softly.assertThat(problem.getTitle())
                .contains("Some of the identifiers requested were rejected");
        softly.assertThat(problem.getDetail())
                .contains("Identifier \"abc12_\" is malformed");
        softly.assertThat(problem.getInstance())
                .contains(URI.create("https://example.com/documents/error.html"));
        softly.assertThat(problem.getIdentifier()).isEmpty();
        softly.assertThat(problem.toString()).isEqualTo(
                "Identifier \"abc12_\" is malformed ("
                        + "Invalid underscore in DNS name \"_example.com\" ‒ "
                        + "This CA will not issue for \"example.net\")");

        var subs = problem.getSubProblems();
        softly.assertThat(subs).isNotNull().hasSize(2);

        var p1 = subs.get(0);
        softly.assertThat(p1.getType()).isEqualTo(URI.create("urn:ietf:params:acme:error:malformed"));
        softly.assertThat(p1.getTitle()).isEmpty();
        softly.assertThat(p1.getDetail())
                .contains("Invalid underscore in DNS name \"_example.com\"");
        softly.assertThat(p1.getIdentifier()).get().extracting("domain").isEqualTo("_example.com");
        softly.assertThat(p1.toString()).isEqualTo("Invalid underscore in DNS name \"_example.com\"");

        var p2 = subs.get(1);
        softly.assertThat(p2.getType())
                .isEqualTo(URI.create("urn:ietf:params:acme:error:rejectedIdentifier"));
        softly.assertThat(p2.getTitle()).isEmpty();
        softly.assertThat(p2.getDetail()).contains("This CA will not issue for \"example.net\"");
        softly.assertThat(p2.getIdentifier()).get().extracting("domain").isEqualTo("example.net");
        softly.assertThat(p2.toString()).isEqualTo("This CA will not issue for \"example.net\"");

        // Verify title fallback when detail is absent.
        var titleOnly = new Problem(
                JSON.parse("{\"type\":\"urn:ietf:params:acme:error:malformed\",\"title\":\"Title only\"}"),
                baseUrl);
        softly.assertThat(titleOnly.toString()).isEqualTo("Title only");

        // Verify type fallback when both detail and title are absent.
        var typeOnly = new Problem(
                JSON.parse("{\"type\":\"urn:ietf:params:acme:error:malformed\"}"),
                baseUrl);
        softly.assertThat(typeOnly.toString())
                .isEqualTo("urn:ietf:params:acme:error:malformed");
    }
}

@Test
public void testEmailAddresses() {
    var builder = Mockito.spy(AccountBuilder.class);

    // Unprefixed addresses gain the mailto scheme, and the builder returns itself.
    assertSame(builder, builder.addEmail("foo@example.com"));
    Mockito.verify(builder).addContact(Mockito.eq("mailto:foo@example.com"));

    // Already-prefixed addresses are forwarded unchanged.
    builder.addEmail("mailto:foo@example.com");
    Mockito.verify(builder, Mockito.times(2)).addContact(Mockito.eq("mailto:foo@example.com"));
}

@Test
public void testInvalidTimeouts() {
    var settings = new NetworkSettings();

    assertThrows(IllegalArgumentException.class,
            () -> settings.setTimeout(null),
            "timeout accepted null");
    assertThrows(IllegalArgumentException.class,
            () -> settings.setTimeout(Duration.ZERO),
            "timeout accepted zero duration");
    assertThrows(IllegalArgumentException.class,
            () -> settings.setTimeout(Duration.ofSeconds(20).negated()),
            "timeout accepted negative duration");

    // A positive timeout is accepted and stored.
    var validTimeout = Duration.ofSeconds(1);
    settings.setTimeout(validTimeout);
    assertEquals(validTimeout, settings.getTimeout());
}
